      var grokOAuthFlowID='';var grokOAuthTimer=0;var pkceOAuthFlowID='';var pkceOAuthProvider='';var editingAccountID=0;var editingKeyID=0;var plaintextKeys={};var pendingCCSwitchKey=null;
      var currentPage='personal';var logs=[];var logTotal=0;var logLimit=50;var logOffset=0;var logSearchTimer=0;var logCopyTexts=[];var personalRecentLogs=[];var landingResolved=false;
      var names={personal:'个人总览',overview:'系统总览',accounts:'订阅管理',keys:'API Key',logs:'调用记录',users:'用户管理',security:'安全设置'};
      function $(id){return document.getElementById(id)}
      function escapeHTML(value){return String(value==null?'':value).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
      function formatNumber(value){return new Intl.NumberFormat('zh-CN',{notation:Number(value)>=10000?'compact':'standard',maximumFractionDigits:1}).format(Number(value)||0)}
      function formatTime(value){if(!value)return '尚未使用';var d=new Date(value);return isNaN(d)?'—':d.toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}
      function pad2(n){return String(n).padStart(2,'0')}
      function formatDuration(ms){ms=Number(ms)||0;if(ms<0)ms=0;var seconds=ms/1000;if(seconds<10)return seconds.toFixed(1)+' 秒';if(seconds<60)return Math.min(59,Math.round(seconds))+' 秒';var totalSec=Math.round(seconds);var min=Math.floor(totalSec/60);var sec=totalSec%60;return sec?min+' 分 '+sec+' 秒':min+' 分钟'}
      function formatDateTime(value){if(!value)return'—';var d=new Date(value);if(isNaN(d))return'—';return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate())+' '+pad2(d.getHours())+':'+pad2(d.getMinutes())+':'+pad2(d.getSeconds())}
      function toast(message,error){var el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('toastStack').appendChild(el);setTimeout(function(){el.remove()},3200)}
      async function request(path,options){options=options||{};options.headers=Object.assign({},options.headers||{},{Authorization:'Bearer '+token,'Content-Type':'application/json'});var response=await fetch(path,options);if(response.status===204)return null;var body={};try{body=await response.json()}catch(e){}if(response.status===401){logout();throw new Error('会话已过期，请重新登录')}if(!response.ok)throw new Error(body.error&&body.error.message||response.statusText);return body}
      function logout(){token='';currentUser=null;landingResolved=false;sessionStorage.removeItem('unisub_admin_token');$('appView').hidden=true;$('loginView').hidden=false;$('password').value=''}
      async function login(event){event.preventDefault();var button=$('loginButton');button.disabled=true;$('loginError').textContent='';try{var response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('username').value.trim(),password:$('password').value})});var body=await response.json();if(!response.ok)throw new Error(body.error&&body.error.message||'登录失败');token=body.token;sessionStorage.setItem('unisub_admin_token',token);showApp()}catch(e){$('loginError').textContent=e.message}finally{button.disabled=false}}
      function showApp(){$('loginView').hidden=true;$('appView').hidden=false;$('serverHost').textContent=location.host;loadData()}
      function navigate(page){if((page==='overview'||page==='accounts'||page==='users')&&!isAdmin())page='personal';currentPage=page;document.querySelectorAll('.page').forEach(function(el){el.hidden=el.id!=='page-'+page});document.querySelectorAll('.nav button').forEach(function(el){el.classList.toggle('active',el.dataset.page===page)});$('crumbText').textContent=names[page];if(page==='personal')renderPersonalOverview();if(page==='overview')renderOverview();if(page==='keys')renderAPIKeys();if(page==='users')renderUsers();if(page==='logs'){fillLogFilters();loadLogs()}}
      function isAdmin(){return currentUser&&currentUser.role==='admin'}
      async function loadData(){try{var me=await request('/api/me');currentUser=me.user||null;if(currentUser){$('serverHost').textContent=currentUser.username+' · '+location.host;$('personalUserBadge').innerHTML='<span class="dot"></span> '+escapeHTML(currentUser.username)}var admin=isAdmin();$('overviewNav').hidden=!admin;$('accountsNav').hidden=!admin;$('usersNav').hidden=!admin;$('logsNav').hidden=!admin;if(!landingResolved){landingResolved=true;navigate(admin?'overview':'personal')}else if(!admin&&(currentPage==='overview'||currentPage==='accounts'||currentPage==='users'||currentPage==='logs'))navigate('personal');var result=await request('/api/subscriptions');accounts=result.data||[];var keyResult=await request('/api/api-keys');keys=keyResult.data||[];users=[];if(admin){var userResult=await request('/api/users');users=userResult.data||[]}var pairs=await Promise.all(accounts.map(async function(a){try{return [a.id,await request('/api/subscriptions/'+a.id+'/usage')]}catch(e){return [a.id,null]}}));usage={};pairs.forEach(function(pair){if(pair[1])usage[pair[0]]=pair[1]});try{var recent=await request('/api/request-logs?limit=8&offset=0');personalRecentLogs=recent.data||[]}catch(e){personalRecentLogs=[]}renderPersonalOverview();renderOverview();renderAccounts();renderAPIKeys();renderUsers();if(isAdmin()&&currentPage==='overview'){loadUsageBySubscription();loadUsageByUser()}if(currentPage==='logs')fillLogFilters()}catch(e){toast(e.message,true)}}
      function totals(){var out={requests:0,input:0,output:0};Object.keys(usage).forEach(function(id){var local=usage[id]&&usage[id].local_usage||{};out.requests+=Number(local.requests_24h)||0;out.input+=Number(local.input_tokens_24h)||0;out.output+=Number(local.output_tokens_24h)||0});return out}
      var usageRange='1d';var userUsageRange='1d';
      var subscriptionUsageResult=null;var userUsageResult=null;
      var subscriptionUsageSort={key:'',direction:1};var userUsageSort={key:'',direction:1};
      function usageQuery(range,fromID,toID){var params=new URLSearchParams();if(range==='custom'){var from=$(fromID).value;var to=$(toID).value;if(!from||!to)throw new Error('请选择起止日期');params.set('from',from);params.set('to',to)}else{params.set('range',range)}return params.toString()}
      function fillUserUsageSubscriptionOptions(){var select=$('userUsageSubscriptionFilter');var selected=select.value;select.innerHTML='<option value="">所有订阅</option>'+accounts.map(function(a){return '<option value="'+a.id+'">'+escapeHTML(a.name)+' · '+escapeHTML(a.provider)+'</option>'}).join('');if(selected&&Array.prototype.some.call(select.options,function(option){return option.value===selected}))select.value=selected;else select.value=''}
      function userUsageQuery(){var params=new URLSearchParams(usageQuery(userUsageRange,'userUsageFrom','userUsageTo'));var subscriptionID=$('userUsageSubscriptionFilter').value;if(subscriptionID)params.set('subscription_id',subscriptionID);return params.toString()}
      async function loadUsageBySubscription(){if(!isAdmin())return;try{var result=await request('/api/usage/by-subscription?'+usageQuery(usageRange,'usageFrom','usageTo'));renderUsageBySubscription(result)}catch(e){toast(e.message,true)}}
      async function loadUsageByUser(){if(!isAdmin())return;try{fillUserUsageSubscriptionOptions();var result=await request('/api/usage/by-user?'+userUsageQuery());renderUsageByUser(result)}catch(e){toast(e.message,true)}}
      function usageSortValue(row,table,key){var u=row.usage||{};if(key==='requests'||key==='input_tokens'||key==='output_tokens'||key==='cache_creation_tokens'||key==='cache_read_tokens'||key==='total_tokens')return Number(u[key])||0;if(key==='subscription')return String(row.subscription_name||('订阅 '+row.subscription_id));if(key==='provider')return String(row.provider||'');if(key==='user')return String(row.username||(row.user_id!=null?'用户 '+row.user_id:'未归属'));if(key==='role')return String(row.role||'');if(key==='enabled')return row.user_id==null?-1:(row.enabled?1:0);return ''}
      function sortUsageRows(rows,table,state){if(!state.key)return rows.slice();return rows.slice().sort(function(a,b){var av=usageSortValue(a,table,state.key);var bv=usageSortValue(b,table,state.key);var compared=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'zh-CN',{numeric:true,sensitivity:'base'});if(!compared){var ai=table==='subscription'?(Number(a.subscription_id)||0):(a.user_id==null?Number.MAX_SAFE_INTEGER:Number(a.user_id));var bi=table==='subscription'?(Number(b.subscription_id)||0):(b.user_id==null?Number.MAX_SAFE_INTEGER:Number(b.user_id));compared=ai-bi}return compared*state.direction})}
      function usageSortHeader(table,key,label,state){var active=state.key===key;var aria=active?(state.direction===1?'ascending':'descending'):'none';var mark=active?(state.direction===1?'↑':'↓'):'↕';return '<th aria-sort="'+aria+'"><button type="button" class="usage-sort'+(active?' active':'')+'" data-usage-sort-table="'+table+'" data-usage-sort-key="'+key+'"><span>'+label+'</span><span class="usage-sort-mark" aria-hidden="true">'+mark+'</span></button></th>'}
      function setUsageSort(table,key){var state=table==='subscription'?subscriptionUsageSort:userUsageSort;if(state.key===key)state.direction*=-1;else{state.key=key;state.direction=1}if(table==='subscription')renderUsageBySubscription(subscriptionUsageResult);else renderUsageByUser(userUsageResult)}
      function usageSortClick(event){var button=event.target.closest('[data-usage-sort-key]');if(button)setUsageSort(button.dataset.usageSortTable,button.dataset.usageSortKey)}
      function renderUsageBySubscription(result){subscriptionUsageResult=result||{data:[],totals:{}};var rows=sortUsageRows(subscriptionUsageResult.data||[],'subscription',subscriptionUsageSort);var totals=subscriptionUsageResult.totals||{};$('usageRangeTotals').textContent='请求 '+formatNumber(totals.requests||0)+' · 输入 '+formatNumber(totals.input_tokens||0)+' · 输出 '+formatNumber(totals.output_tokens||0)+' · 缓存创建 '+formatNumber(totals.cache_creation_tokens||0)+' · 缓存读取 '+formatNumber(totals.cache_read_tokens||0);if(!rows.length){$('usageBySubscriptionTable').innerHTML='<div class="empty">所选时间范围内暂无用量。</div>';return}$('usageBySubscriptionTable').innerHTML='<table><thead><tr>'+usageSortHeader('subscription','subscription','订阅',subscriptionUsageSort)+usageSortHeader('subscription','provider','平台',subscriptionUsageSort)+usageSortHeader('subscription','requests','请求',subscriptionUsageSort)+usageSortHeader('subscription','input_tokens','输入',subscriptionUsageSort)+usageSortHeader('subscription','output_tokens','输出',subscriptionUsageSort)+usageSortHeader('subscription','cache_creation_tokens','缓存创建',subscriptionUsageSort)+usageSortHeader('subscription','cache_read_tokens','缓存读取',subscriptionUsageSort)+usageSortHeader('subscription','total_tokens','合计 Token',subscriptionUsageSort)+'</tr></thead><tbody>'+rows.map(function(row){var u=row.usage||{};return '<tr><td><div class="account-name">'+escapeHTML(row.subscription_name||('订阅 '+row.subscription_id))+'</div><div class="subtle">ID '+row.subscription_id+'</div></td><td>'+escapeHTML(row.provider||'')+'</td><td>'+formatNumber(u.requests||0)+'</td><td>'+formatNumber(u.input_tokens||0)+'</td><td>'+formatNumber(u.output_tokens||0)+'</td><td>'+formatNumber(u.cache_creation_tokens||0)+'</td><td>'+formatNumber(u.cache_read_tokens||0)+'</td><td>'+formatNumber(u.total_tokens||0)+'</td></tr>'}).join('')+'</tbody></table>'}
      function renderUsageByUser(result){userUsageResult=result||{data:[],totals:{}};var rows=sortUsageRows(userUsageResult.data||[],'user',userUsageSort);var totals=userUsageResult.totals||{};$('usageByUserTotals').textContent='请求 '+formatNumber(totals.requests||0)+' · 输入 '+formatNumber(totals.input_tokens||0)+' · 输出 '+formatNumber(totals.output_tokens||0)+' · 缓存创建 '+formatNumber(totals.cache_creation_tokens||0)+' · 缓存读取 '+formatNumber(totals.cache_read_tokens||0);if(!rows.length){$('usageByUserTable').innerHTML='<div class="empty">所选时间范围内暂无用户用量。</div>';return}$('usageByUserTable').innerHTML='<table><thead><tr>'+usageSortHeader('user','user','用户',userUsageSort)+usageSortHeader('user','role','角色',userUsageSort)+usageSortHeader('user','enabled','状态',userUsageSort)+usageSortHeader('user','requests','请求',userUsageSort)+usageSortHeader('user','input_tokens','输入',userUsageSort)+usageSortHeader('user','output_tokens','输出',userUsageSort)+usageSortHeader('user','cache_creation_tokens','缓存创建',userUsageSort)+usageSortHeader('user','cache_read_tokens','缓存读取',userUsageSort)+usageSortHeader('user','total_tokens','合计 Token',userUsageSort)+'</tr></thead><tbody>'+rows.map(function(row){var u=row.usage||{};var assigned=row.user_id!=null;return '<tr><td><div class="account-name">'+escapeHTML(row.username||(assigned?'用户 '+row.user_id:'未归属'))+'</div>'+(assigned?'<div class="subtle">ID '+row.user_id+'</div>':'<div class="subtle">旧 Key 或无法识别的历史调用</div>')+'</td><td>'+escapeHTML(row.role==='admin'?'管理员':(row.role==='user'?'用户':'—'))+'</td><td>'+(assigned?'<span class="badge '+(row.enabled?'ok':'off')+'">'+(row.enabled?'已启用':'已停用')+'</span>':'—')+'</td><td>'+formatNumber(u.requests||0)+'</td><td>'+formatNumber(u.input_tokens||0)+'</td><td>'+formatNumber(u.output_tokens||0)+'</td><td>'+formatNumber(u.cache_creation_tokens||0)+'</td><td>'+formatNumber(u.cache_read_tokens||0)+'</td><td>'+formatNumber(u.total_tokens||0)+'</td></tr>'}).join('')+'</tbody></table>'}
      function setUsageRange(range){usageRange=range;['1d','1w','1m','custom'].forEach(function(name){var button=$('usageRange'+name.toUpperCase());if(button)button.classList.toggle('active',usageRange===name)});$('usageCustomFields').hidden=usageRange!=='custom';if(usageRange!=='custom')loadUsageBySubscription()}
      function setUserUsageRange(range){userUsageRange=range;['1d','1w','1m','custom'].forEach(function(name){var button=$('userUsageRange'+name.toUpperCase());if(button)button.classList.toggle('active',userUsageRange===name)});$('userUsageCustomFields').hidden=userUsageRange!=='custom';if(userUsageRange!=='custom')loadUsageByUser()}

      function personalKeyAccountIDs(){var set={};keys.forEach(function(k){set[k.subscription_id]=true});return Object.keys(set).map(Number)}
      function personalTotals(){var out={requests:0,input:0,output:0};personalKeyAccountIDs().forEach(function(id){var local=usage[id]&&usage[id].local_usage||{};out.requests+=Number(local.requests_24h)||0;out.input+=Number(local.input_tokens_24h)||0;out.output+=Number(local.output_tokens_24h)||0});return out}
      function providerIcon(p){return '<span class="provider-logo '+escapeHTML(p)+'">'+({claude:'C',codex:'O',grok:'G'}[p]||'?')+'</span>'}
      function renderOverview(){var t=totals();$('statAccounts').textContent=formatNumber(accounts.length);$('statEnabled').textContent=accounts.filter(function(a){return a.enabled}).length+' 个已启用';$('statRequests').textContent=formatNumber(t.requests);$('statInput').textContent=formatNumber(t.input);$('statOutput').textContent=formatNumber(t.output);var counts={claude:0,codex:0,grok:0};accounts.forEach(function(a){counts[a.provider]=(counts[a.provider]||0)+1});var max=Math.max(1,counts.claude,counts.codex,counts.grok);$('providerBars').innerHTML=['claude','codex','grok'].map(function(p){return '<div class="provider-row"><div class="provider-name">'+providerIcon(p)+p.charAt(0).toUpperCase()+p.slice(1)+'</div><div class="bar"><i style="width:'+Math.round(counts[p]/max*100)+'%"></i></div><div class="provider-count">'+counts[p]+'</div></div>'}).join('');var recent=accounts.slice().sort(function(a,b){return new Date(b.last_used_at||b.created_at)-new Date(a.last_used_at||a.created_at)}).slice(0,4);$('recentActivity').innerHTML=recent.length?recent.map(function(a){return '<div class="activity-item"><span class="dot" style="margin-top:7px;background:'+(a.enabled?'var(--green)':'#69768a')+'"></span><div><p>'+escapeHTML(a.name)+'</p><small>'+escapeHTML(a.provider)+' · '+formatTime(a.last_used_at)+'</small></div><span class="badge '+(a.enabled?'ok':'off')+'">'+(a.enabled?'已启用':'已停用')+'</span></div>'}).join(''):'<div class="empty">还没有账号，先接入一个上游订阅吧。</div>'}
      function renderPersonalOverview(){var mine=keys;var t=personalTotals();$('personalStatKeys').textContent=formatNumber(mine.length);$('personalStatKeysEnabled').textContent=mine.filter(function(k){return k.enabled}).length+' 个已启用';$('personalStatRequests').textContent=formatNumber(t.requests);$('personalStatInput').textContent=formatNumber(t.input);$('personalStatOutput').textContent=formatNumber(t.output);var counts={claude:0,codex:0,grok:0};mine.forEach(function(k){counts[k.provider]=(counts[k.provider]||0)+1});var max=Math.max(1,counts.claude,counts.codex,counts.grok);$('personalKeyBars').innerHTML=mine.length?['claude','codex','grok'].map(function(p){return '<div class="provider-row"><div class="provider-name">'+providerIcon(p)+p.charAt(0).toUpperCase()+p.slice(1)+'</div><div class="bar"><i style="width:'+Math.round(counts[p]/max*100)+'%"></i></div><div class="provider-count">'+counts[p]+'</div></div>'}).join(''):'<div class="empty">还没有 API Key。先到 API Key 页面签发。</div>';var recent=personalRecentLogs.slice(0,5);$('personalRecentCalls').innerHTML=recent.length?recent.map(function(log){var ok=log.status_code>=200&&log.status_code<300;return '<div class="activity-item"><span class="dot" style="margin-top:7px;background:'+(ok?'var(--green)':(log.status_code===429||log.status_code===499?'var(--orange)':'var(--red)'))+'"></span><div><p>'+escapeHTML(log.model||log.provider||log.path||'调用')+'</p><small>'+escapeHTML(formatDateTime(log.started_at))+' · '+escapeHTML(log.subscription_name||'未绑定')+' · '+formatDuration(log.duration_ms)+'</small></div><span class="badge '+statusClass(log.status_code)+'">'+log.status_code+'</span></div>'}).join(''):'<div class="empty">暂无调用记录。</div>'}
      function quotaWindowName(name){return({five_hour:'5 小时',five_hours:'5 小时',daily:'每日',seven_day:'7 天',seven_day_sonnet:'Sonnet 7 天',seven_day_opus:'Opus 7 天',weekly:'每周',monthly:'每月'}[String(name||'').toLowerCase()]||String(name||'Usage'))}
      function usagePercent(value){if(!value||typeof value!=='object')return null;var used=Number(value.used_percent);if(Number.isFinite(used))return Math.max(0,Math.min(100,used));var remaining=Number(value.remaining_percent);if(Number.isFinite(remaining))return Math.max(0,Math.min(100,100-remaining));var usedCount=value.used;if(usedCount==null)usedCount=value.used_count;if(usedCount==null)usedCount=value.used_tokens;var remainingCount=value.remaining;if(remainingCount==null)remainingCount=value.remaining_count;if(remainingCount==null)remainingCount=value.remaining_tokens;if(remainingCount==null)remainingCount=value.balance;var limit=value.limit;if(limit==null)limit=value.total;if(limit==null)limit=value.cap;if(usedCount==null&&remainingCount!=null&&limit!=null)usedCount=Number(limit)-Number(remainingCount);if(Number.isFinite(Number(usedCount))&&Number(limit)>0)return Math.max(0,Math.min(100,Number(usedCount)/Number(limit)*100));return null}
      function formatUsagePercent(percent){return percent.toFixed(1).replace(/\.0$/,'')+'%'}
      function quotaPercent(window){return usagePercent(window)}
      function quotaObjectLine(value,label){var percent=usagePercent(value);if(percent===null)return'';var detail=label+(value&&value.reset_at?' · '+formatTime(value.reset_at):'');return '<div class="quota-window"><b>'+escapeHTML(formatUsagePercent(percent))+'</b><small>'+escapeHTML(detail)+'</small></div>'}
      function creditBalanceLine(value,label){var percent=value!=null&&typeof value==='object'?usagePercent(value):null;if(percent===null)return'';return '<div class="quota-window"><b>'+escapeHTML(formatUsagePercent(percent))+'</b><small>'+escapeHTML(label)+'</small></div>'}
      function renderQuota(account){var q=usage[account.id];if(!q||q.status!=='available'){var detail=q&&q.error?String(q.error):'暂无上游 Usage';return '<div class="quota-unknown" title="'+escapeHTML(detail)+'"><span class="badge warn">未知</span><small>'+escapeHTML(detail)+'</small></div>'}var windows=Array.isArray(q.windows)?q.windows:[];var lines=windows.slice(0,2).map(function(window){var percent=quotaPercent(window);if(percent===null)return'';var detail=quotaWindowName(window.name)+(window.reset_at?' · '+formatTime(window.reset_at):'');return '<div class="quota-window"><b>'+escapeHTML(formatUsagePercent(percent))+'</b><small>'+escapeHTML(detail)+'</small></div>'}).filter(Boolean);if(!lines.length){var requestLine=quotaObjectLine(q.request_quota,'请求');var tokenLine=quotaObjectLine(q.token_quota,'Token');if(requestLine)lines.push(requestLine);if(tokenLine)lines.push(tokenLine)}var credits=q.credit_balance||{};var prepaidLine=creditBalanceLine(credits.prepaid,'Prepaid');var onDemandLine=creditBalanceLine(credits.on_demand,'On-demand');if(prepaidLine)lines.push(prepaidLine);if(onDemandLine)lines.push(onDemandLine);if(!lines.length)return '<div class="quota-unknown"><span class="badge warn">未知</span><small>上游未返回 Usage</small></div>';var tier=q.subscription_tier?'<div class="quota-tier">'+escapeHTML(q.subscription_tier)+'</div>':'';var checked=q.checked_at?'<div class="quota-checked">'+(q.stale?'数据可能已过期 · ':'查询于 ')+escapeHTML(formatTime(q.checked_at))+'</div>':'';var refreshError=q.error?'<div class="quota-checked" title="'+escapeHTML(q.error)+'">最近查询失败，保留上次数据</div>':'';return '<div class="quota-cell">'+tier+lines.join('')+checked+refreshError+'</div>'}
      function formatLocalTokens(local,available){if(!available)return'—';var input=Number(local.input_tokens_24h)||0;var output=Number(local.output_tokens_24h)||0;var cacheCreate=Number(local.cache_creation_tokens_24h)||0;var cacheRead=Number(local.cache_read_tokens_24h)||0;var total=local.total_tokens_24h!=null?Number(local.total_tokens_24h):(input+output);return'<div class="subtle">输入 '+escapeHTML(formatNumber(input))+' · 输出 '+escapeHTML(formatNumber(output))+'</div><div class="subtle">缓存创建 '+escapeHTML(formatNumber(cacheCreate))+' · 缓存读取 '+escapeHTML(formatNumber(cacheRead))+'</div><div class="subtle">总数 '+escapeHTML(formatNumber(total))+'</div>'}
      function canRefreshUsage(account){return!!(account&&account.auth_type==='oauth'&&(account.provider==='grok'||account.provider==='claude'||account.provider==='codex'))}
      function actionIcon(name){return({refresh:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M21 12a9 9 0 11-2.6-6.4"/><path d="M21 3v6h-6"/></svg>',edit:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 20h4L19 9l-4-4L4 16v4z"/><path d="M13 7l4 4"/></svg>',trash:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 7h16M9 7V5h6v2M6 7l1 13h10l1-13M10 11v6M14 11v6"/></svg>',ccswitch:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 7h11l-3-3M18 7l-3 3"/><path d="M17 17H6l3 3M6 17l3-3"/></svg>'}[name]||'')}
      function iconActionButton(action,id,title,icon,extraClass){return '<button class="btn icon-btn'+(extraClass?' '+extraClass:'')+'" type="button" data-action="'+action+'" data-id="'+id+'" title="'+title+'" aria-label="'+title+'">'+actionIcon(icon)+'</button>'}
      function renderAccounts(){var query=$('accountSearch').value.trim().toLowerCase();var provider=$('providerFilter').value;var filtered=accounts.filter(function(a){return(!provider||a.provider===provider)&&(!query||(a.name+' '+a.provider).toLowerCase().includes(query))});if(!filtered.length){$('accountTable').innerHTML='<div class="empty">'+(accounts.length?'没有匹配的账号。':'暂无账号。先接入一个上游订阅吧。')+'</div>';return}$('accountTable').innerHTML='<table><thead><tr><th>账号</th><th>平台</th><th>状态</th><th>Usage</th><th>24h 请求</th><th>Token</th><th style="text-align:right">操作</th></tr></thead><tbody>'+filtered.map(function(a){var available=!!usage[a.id];var u=available&&usage[a.id].local_usage||{};var metric=function(value){return available?formatNumber(value):'—'};return '<tr><td><div class="account-name">'+escapeHTML(a.name)+'</div><div class="subtle">ID '+a.id+' · '+escapeHTML(a.auth_type)+(a.proxy_configured?' · 已配置代理':'')+(a.concurrency_queue_timeout_seconds?' · 队列 '+a.concurrency_queue_timeout_seconds+'s':' · 队列继承全局')+'</div></td><td><div class="provider-name">'+providerIcon(a.provider)+escapeHTML(a.provider)+'</div></td><td><span class="badge '+(a.enabled?'ok':'off')+'"><span class="dot" style="background:'+(a.enabled?'var(--green)':'#748196')+'"></span>'+(a.enabled?'已启用':'已停用')+'</span></td><td>'+renderQuota(a)+'</td><td>'+metric(u.requests_24h)+'</td><td>'+formatLocalTokens(u,available)+'</td><td><div class="actions">'+(canRefreshUsage(a)?iconActionButton('refresh-usage',a.id,'刷新 Usage','refresh'):'')+iconActionButton('edit',a.id,'编辑','edit')+iconActionButton('delete',a.id,'删除','trash','btn-danger')+'</div></td></tr>'}).join('')+'</tbody></table>'}
      function setAccountModalMode(account){editingAccountID=account?account.id:0;var editing=!!editingAccountID;document.querySelectorAll('#accountForm .create-only').forEach(function(el){el.hidden=editing});document.querySelectorAll('#accountForm .edit-only').forEach(function(el){el.hidden=!editing});$('accountProvider').disabled=editing;$('authType').disabled=editing;$('accountModalTitle').textContent=editing?'编辑账号':'接入上游账号';$('deleteAccountButton').hidden=!editing;$('refreshUsageButton').hidden=!(editing&&canRefreshUsage(account));$('clearProxyField').hidden=!(editing&&account&&account.proxy_configured);$('clearProxy').checked=false;$('proxyHint').textContent=editing&&account&&account.proxy_configured?'已配置代理。留空保持不变，勾选下方选项可清除。':'代理地址以明文保存，管理 API 不会回显。';updateCredentialHint()}
      function openAccountModal(){$('accountForm').reset();$('concurrencyLimit').value='1';$('concurrencyQueueTimeoutSeconds').value='0';$('credentials').value='';$('accountEnabled').value='1';setAccountModalMode(null);$('accountModal').hidden=false;$('accountName').focus()}
      function prettyJSON(value){if(value==null||value==='')return'';if(typeof value==='string'){try{return JSON.stringify(JSON.parse(value),null,2)}catch(e){return value}}try{return JSON.stringify(value,null,2)}catch(e){return''}}
      async function openEditAccount(account){$('accountForm').reset();$('accountName').value=account.name;$('accountProvider').value=account.provider;$('authType').value=account.auth_type;$('accountEnabled').value=account.enabled?'1':'0';$('concurrencyLimit').value=String(account.concurrency_limit||1);$('concurrencyQueueTimeoutSeconds').value=String(account.concurrency_queue_timeout_seconds||0);$('proxyURL').value='';$('credentials').value='';setAccountModalMode(account);$('accountModal').hidden=false;$('accountName').focus();try{var detail=await request('/api/subscriptions/'+account.id);$('credentials').value=prettyJSON(detail.subscription&&detail.subscription.credentials)}catch(e){toast(e.message,true)}}
      function closeAccountModal(){editingAccountID=0;$('accountModal').hidden=true}
      function updateCredentialHint(){var editing=!!editingAccountID;var p=$('accountProvider').value;var auth=$('authType').value;var webLogin=!editing&&auth==='oauth'&&(p==='grok'||p==='claude'||p==='codex');$('credentials').required=!webLogin;$('credentials').disabled=webLogin;$('tokenExpiresAt').disabled=editing||webLogin;if(editing){$('credentials').placeholder='{"access_token":"..."}';$('credentialHint').textContent='保存修改时会写入当前 JSON。';$('createButton').textContent='保存修改';return}if(p==='grok'&&auth==='oauth'&&!editing){$('credentials').placeholder='由 xAI OAuth 登录自动填写';$('credentialHint').textContent='提交后会显示 xAI 设备授权码，登录成功后自动保存并续期 Token。';$('createButton').textContent='登录并绑定 Grok'}else if(p==='claude'&&auth==='oauth'&&!editing){$('credentials').placeholder='由 Claude 网页登录自动填写';$('credentialHint').textContent='提交后会打开 Claude 官方授权页。登录完成后把授权码粘贴回来，Token 会自动保存并续期。';$('createButton').textContent='登录并绑定 Claude'}else if(p==='codex'&&auth==='oauth'&&!editing){$('credentials').placeholder='由 Codex 网页登录自动填写';$('credentialHint').textContent='提交后会打开 ChatGPT 官方授权页。完成后把回调 URL 粘贴回来，Token 会自动保存并续期。';$('createButton').textContent='登录并绑定 Codex'}else if(auth==='api_key'){$('credentials').placeholder='{"api_key":"..."}';$('credentialHint').textContent='填入上游平台 API Key。';$('createButton').textContent='创建账号'}else{$('credentials').placeholder='{"access_token":"...","refresh_token":"..."}';$('credentialHint').textContent='凭据以明文保存。';$('createButton').textContent='创建账号'}}
      function accountFormPayload(){var payload={name:$('accountName').value.trim(),concurrency_limit:Number($('concurrencyLimit').value)||1,concurrency_queue_timeout_seconds:Number($('concurrencyQueueTimeoutSeconds').value)||0};if($('proxyURL').value.trim())payload.proxy_url=$('proxyURL').value.trim();return payload}
      async function saveAccount(event){event.preventDefault();var button=$('createButton');button.disabled=true;try{if(editingAccountID){var account=accounts.find(function(item){return item.id===editingAccountID});var payload=accountFormPayload();payload.enabled=$('accountEnabled').value==='1';if($('clearProxy').checked)payload.proxy_url='';else if(!payload.proxy_url&&account&&account.proxy_configured)delete payload.proxy_url;try{payload.credentials=JSON.parse($('credentials').value)}catch(e){toast('凭据 JSON 无效',true);return}await request('/api/subscriptions/'+editingAccountID,{method:'PUT',body:JSON.stringify(payload)});closeAccountModal();toast('账号已更新');await loadData();return}var provider=$('accountProvider').value;var auth=$('authType').value;var payload=accountFormPayload();if(auth==='oauth'&&(provider==='grok'||provider==='claude'||provider==='codex')){closeAccountModal();if(provider==='grok'){$('grokOAuthModal').hidden=false;$('grokOAuthCode').textContent='—';$('grokOAuthStatus').textContent='正在向 xAI 申请登录码…';$('grokOAuthOpen').href='#';var started=await request('/api/providers/grok/oauth/device/start',{method:'POST',body:JSON.stringify(payload)});grokOAuthFlowID=started.flow_id;$('grokOAuthCode').textContent=started.user_code;$('grokOAuthOpen').href=started.verification_uri_complete||started.verification_uri;$('grokOAuthStatus').textContent='请打开授权页面并输入上方代码，完成后本页会自动继续。';scheduleGrokOAuthPoll((Number(started.interval)||5)*1000);return}await startPKCEOAuth(provider,payload);return}payload.provider=provider;payload.auth_type=auth;payload.credentials=JSON.parse($('credentials').value);if($('tokenExpiresAt').value)payload.token_expires_at=new Date($('tokenExpiresAt').value).toISOString();await request('/api/subscriptions',{method:'POST',body:JSON.stringify(payload)});closeAccountModal();toast('账号已创建，请到 API Key 页面签发调用密钥');await loadData()}catch(e){$('grokOAuthModal').hidden=true;$('pkceOAuthModal').hidden=true;toast(e.message,true)}finally{button.disabled=false}}
      function scheduleGrokOAuthPoll(delay){clearTimeout(grokOAuthTimer);if(!grokOAuthFlowID)return;grokOAuthTimer=setTimeout(pollGrokOAuth,Math.max(1000,delay||5000))}
      async function pollGrokOAuth(){if(!grokOAuthFlowID)return;try{var result=await request('/api/providers/grok/oauth/device/poll',{method:'POST',body:JSON.stringify({flow_id:grokOAuthFlowID})});if(result.status==='complete'){grokOAuthFlowID='';$('grokOAuthModal').hidden=true;toast('Grok 账号绑定成功，请到 API Key 页面签发调用密钥');await loadData();return}$('grokOAuthStatus').textContent='等待你在 xAI 页面确认授权…';scheduleGrokOAuthPoll((Number(result.retry_after)||5)*1000)}catch(e){grokOAuthFlowID='';$('grokOAuthModal').hidden=true;toast(e.message,true)}}
      function cancelGrokOAuth(){grokOAuthFlowID='';clearTimeout(grokOAuthTimer);$('grokOAuthModal').hidden=true}
      function pkceProviderLabel(provider){return provider==='codex'?'Codex':'Claude'}
      function pkceStartPath(provider){return provider==='codex'?'/api/providers/codex/oauth/start':'/api/providers/claude/oauth/start'}
      function pkceExchangePath(provider){return provider==='codex'?'/api/providers/codex/oauth/exchange':'/api/providers/claude/oauth/exchange'}
      async function startPKCEOAuth(provider,payload){pkceOAuthFlowID='';pkceOAuthProvider=provider;$('pkceOAuthModal').hidden=false;$('pkceOAuthTitle').textContent='登录 '+pkceProviderLabel(provider);$('pkceOAuthNotice').textContent='请在 '+pkceProviderLabel(provider)+' 官方页面完成授权。UniSub 不会接触你的账号密码。';$('pkceOAuthOpen').href='#';$('pkceOAuthOpen').textContent='打开 '+pkceProviderLabel(provider)+' 授权页面';$('pkceOAuthCode').value='';$('pkceOAuthStatus').textContent='正在生成授权链接…';$('pkceOAuthHint').textContent=provider==='codex'?'授权完成后浏览器会跳转到 localhost:1455。即使页面打不开，也把地址栏完整 URL 粘贴到这里。':'授权完成后把官方页面显示的授权码完整粘贴到这里，包含 # 后面的部分。';var started=await request(pkceStartPath(provider),{method:'POST',body:JSON.stringify(payload)});pkceOAuthFlowID=started.flow_id;$('pkceOAuthOpen').href=started.authorization_url;$('pkceOAuthStatus').textContent='请打开授权页面登录，完成后把授权码或回调地址粘贴到下方。'}
      async function submitPKCEOAuth(){if(!pkceOAuthFlowID||!pkceOAuthProvider)return;var button=$('pkceOAuthSubmit');button.disabled=true;try{await request(pkceExchangePath(pkceOAuthProvider),{method:'POST',body:JSON.stringify({flow_id:pkceOAuthFlowID,code:$('pkceOAuthCode').value.trim()})});pkceOAuthFlowID='';pkceOAuthProvider='';$('pkceOAuthModal').hidden=true;toast('账号绑定成功，请到 API Key 页面签发调用密钥');await loadData()}catch(e){toast(e.message,true)}finally{button.disabled=false}}
      function cancelPKCEOAuth(){pkceOAuthFlowID='';pkceOAuthProvider='';$('pkceOAuthModal').hidden=true;$('pkceOAuthCode').value=''}
      async function refreshData(){var button=$('refreshButton');button.disabled=true;try{if(currentPage==='logs'){await loadLogs();toast('调用记录已刷新');return}await loadData();if(currentPage==='overview')await loadUsageBySubscription();toast('数据已刷新')}finally{button.disabled=false}}
      function showKey(key,title,meta){$('keyTitle').textContent=title;$('newAPIKey').value=key;pendingCCSwitchKey=meta||null;if(meta&&meta.id)plaintextKeys[meta.id]=key;$('ccSwitchFromKeyModal').hidden=!meta;$('keyModal').hidden=false}
      async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制到剪贴板')}catch(e){var input=document.createElement('textarea');input.value=text;document.body.appendChild(input);input.select();document.execCommand('copy');input.remove();toast('已复制到剪贴板')}}
      function editingAccount(){return accounts.find(function(a){return a.id===editingAccountID})}
      async function accountAction(event){var button=event.target.closest('[data-action]');if(!button)return;var id=Number(button.dataset.id);var account=accounts.find(function(a){return a.id===id});if(!account)return;if(button.dataset.action==='edit')openEditAccount(account);if(button.dataset.action==='delete')deleteAccount(account);if(button.dataset.action==='refresh-usage')refreshAccountUsage(account,button)}
      async function refreshAccountUsage(account,button){if(!account||!canRefreshUsage(account))return;if(button)button.disabled=true;try{await request('/api/subscriptions/'+account.id+'/usage/refresh',{method:'POST'});toast(account.name+' 的 Usage 已刷新');await loadData()}catch(e){toast(e.message,true)}finally{if(button)button.disabled=false}}
      async function refreshEditingUsage(){return refreshAccountUsage(editingAccount(),$('refreshUsageButton'))}
      async function deleteAccount(account){if(!account||!confirm('确定删除 '+account.name+' ？其 API Key 和用量记录也将被删除。'))return;try{await request('/api/subscriptions/'+account.id,{method:'DELETE'});closeAccountModal();toast('账号已删除');await loadData()}catch(e){toast(e.message,true)}}
      async function deleteEditingAccount(){return deleteAccount(editingAccount())}
      function statusClass(code){if(code>=200&&code<300)return'ok';if(code===429||code===499)return'warn';if(code>=400)return'off';return''}
      function formatTokens(log){if(log.input_tokens==null&&log.output_tokens==null&&log.cache_read_tokens==null&&log.cache_creation_tokens==null&&log.total_tokens==null)return'—';var total=log.total_tokens!=null?log.total_tokens:(Number(log.input_tokens)||0)+(Number(log.output_tokens)||0);return'<div class="subtle">输入 '+escapeHTML(formatNumber(log.input_tokens||0))+' · 输出 '+escapeHTML(formatNumber(log.output_tokens||0))+'</div><div class="subtle">缓存创建 '+escapeHTML(formatNumber(log.cache_creation_tokens||0))+' · 缓存读取 '+escapeHTML(formatNumber(log.cache_read_tokens||0))+'</div><div class="subtle">合计 '+escapeHTML(formatNumber(total))+'</div>'}
      function fillLogFilters(){var admin=isAdmin();$('logAccountFilter').hidden=!admin;if(!admin){$('logAccountFilter').value='';return}var selected=$('logAccountFilter').value;var options='<option value="">全部订阅</option>'+accounts.map(function(a){return '<option value="'+a.id+'">'+escapeHTML(a.name)+' · '+escapeHTML(a.provider)+'</option>'}).join('');$('logAccountFilter').innerHTML=options;if(selected&&Array.prototype.some.call($('logAccountFilter').options,function(o){return o.value===selected}))$('logAccountFilter').value=selected;else $('logAccountFilter').value=''}
      function logQueryParams(){var params=new URLSearchParams({limit:String(logLimit),offset:String(logOffset)});if(isAdmin()&&$('logAccountFilter').value)params.set('subscription_id',$('logAccountFilter').value);if($('logStatusFilter').value)params.set('status',$('logStatusFilter').value);if($('logSearch').value.trim())params.set('q',$('logSearch').value.trim());return params}
      async function loadLogs(){fillLogFilters();try{var result=await request('/api/request-logs?'+logQueryParams());logs=result.data||[];logTotal=Number(result.total)||0;logLimit=Number(result.limit)||logLimit;logOffset=Number(result.offset)||0;renderLogs()}catch(e){toast(e.message,true)}}
      function logKeyLabel(log){var name=String(log.api_key_name||'').trim();var prefix=String(log.api_key_prefix||'').trim();if(!name&&!prefix)return'';if(name&&prefix)return'Key '+name+' · '+prefix+'…';if(name)return'Key '+name;return'Key '+prefix+'…'}
      function renderLogs(){if(!logs.length){$('logTable').innerHTML='<div class="empty">暂无调用记录。转发请求后会出现在这里。</div>';$('logPager').innerHTML='';return}$('logTable').innerHTML='<table><thead><tr><th>ID</th><th>模型</th><th>订阅</th><th>状态</th><th>Token</th></tr></thead><tbody>'+logs.map(function(log){var path=escapeHTML(log.path||'')+(log.query?'?'+escapeHTML(log.query):'');var account=escapeHTML(log.subscription_name||(log.subscription_id?'订阅 '+log.subscription_id:'未绑定'));var keyLabel=logKeyLabel(log);return '<tr class="click-row" data-log-day="'+escapeHTML(log.day)+'" data-log-id="'+log.id+'"><td><div class="account-name">#'+log.id+' <span class="subtle">'+escapeHTML(formatDateTime(log.started_at))+'</span></div><div class="subtle">'+escapeHTML(log.client_ip||'')+(log.client_ip&&log.request_id?' · ':'')+escapeHTML(log.request_id||'')+'</div></td><td><div class="account-name">'+escapeHTML(log.model||log.provider||'—')+'</div><div class="subtle">'+escapeHTML(log.method)+' '+path+'</div></td><td><div class="account-name">'+account+'</div>'+(keyLabel?'<div class="subtle">'+escapeHTML(keyLabel)+'</div>':'')+'</td><td><span class="badge '+statusClass(log.status_code)+'">'+log.status_code+'</span> <span class="subtle">'+formatDuration(log.duration_ms)+'</span>'+(log.error_type?'<div class="subtle">'+escapeHTML(log.error_type)+'</div>':'')+'</td><td>'+formatTokens(log)+'</td></tr>'}).join('')+'</tbody></table>';var from=logTotal?logOffset+1:0;var to=Math.min(logOffset+logs.length,logTotal);$('logPager').innerHTML='<span>'+from+'-'+to+' / '+formatNumber(logTotal)+'</span><button class="btn" type="button" id="logPrev"'+(logOffset<=0?' disabled':'')+'>上一页</button><button class="btn" type="button" id="logNext"'+(logOffset+logLimit>=logTotal?' disabled':'')+'>下一页</button>'}
      function formatLogJSON(value){if(!value)return'';try{return JSON.stringify(JSON.parse(value),null,2)}catch(e){return String(value)}}
      function formatLogHeaders(value){if(!value)return'';try{var parsed=JSON.parse(value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))return String(value);return Object.keys(parsed).map(function(key){var vals=parsed[key];if(!Array.isArray(vals))vals=[vals];return vals.map(function(item){return key+': '+item}).join('\n')}).filter(Boolean).join('\n')}catch(e){return String(value)}}
      function logCopyButton(text){var content=text||'';var idx=logCopyTexts.length;logCopyTexts.push(content);return '<button class="btn log-copy" type="button" data-copy-index="'+idx+'"'+(content?'':' disabled')+'>复制</button>'}
      function logBlock(title,hint,text){var content=text||'';return '<div class="field log-block"><div class="log-block-head"><button class="log-toggle" type="button" data-log-toggle aria-expanded="true"><span class="log-chevron" aria-hidden="true"></span><span>'+escapeHTML(title)+'</span></button>'+logCopyButton(content)+'</div>'+(hint?'<div class="subtle log-block-hint">'+hint+'</div>':'')+'<pre class="log-pre">'+escapeHTML(content||'—')+'</pre></div>'}
      function logMetaItem(label,value,copyable){var text=value||'';return '<div><small>'+escapeHTML(label)+'</small><div class="log-meta-value"><b>'+escapeHTML(text||'—')+'</b>'+(copyable&&text?logCopyButton(text):'')+'</div></div>'}
      async function openLog(day,id){try{var result=await request('/api/request-logs/'+encodeURIComponent(day)+'/'+id);var log=result.log||{};logCopyTexts=[];var requestLine=escapeHTML(log.method)+' '+escapeHTML(log.path||'')+(log.query?'?'+escapeHTML(log.query):'');$('logModalBody').innerHTML='<div class="log-meta">'+logMetaItem('日志 ID',(log.day||day)+' / #'+(log.id||id),true)+logMetaItem('订阅',log.subscription_name||'',true)+logMetaItem('模型',log.model||'',true)+'<div><small>Token</small>'+formatTokens(log)+'</div>'+logMetaItem('来源 IP',log.client_ip||'',true)+logMetaItem('Request ID',log.request_id||'',true)+logMetaItem('错误',log.error_type||'',true)+'<div><small>耗时</small><b>'+formatDuration(log.duration_ms)+'</b></div></div>'+logBlock('Request Headers',requestLine,formatLogHeaders(log.request_headers))+logBlock('Request Body',log.request_truncated?'已截断':'',formatLogJSON(log.request_body)||log.request_body||'')+logBlock('Response Headers','HTTP '+log.status_code,formatLogHeaders(log.response_headers))+logBlock('Response Body',log.response_truncated?'已截断':'',formatLogJSON(log.response_body)||log.response_body||'');$('logModal').hidden=false}catch(e){toast(e.message,true)}}
      function logModalClick(event){var copy=event.target.closest('[data-copy-index]');if(copy){if(!copy.disabled)copyText(logCopyTexts[Number(copy.dataset.copyIndex)]||'');return}var head=event.target.closest('.log-block-head');if(!head)return;var block=head.closest('.log-block');if(!block)return;var collapsed=block.classList.toggle('collapsed');var toggle=block.querySelector('[data-log-toggle]');if(toggle)toggle.setAttribute('aria-expanded',collapsed?'false':'true')}
      function logTableClick(event){var row=event.target.closest('[data-log-day]');if(!row)return;openLog(row.dataset.logDay,row.dataset.logId)}
      function logPagerClick(event){if(event.target.id==='logPrev'&&logOffset>0){logOffset=Math.max(0,logOffset-logLimit);loadLogs()}if(event.target.id==='logNext'&&logOffset+logLimit<logTotal){logOffset+=logLimit;loadLogs()}}
      function resetLogOffsetAndLoad(){logOffset=0;loadLogs()}
      function fillAPIKeyAccountOptions(selected){var filter=$('keyAccountFilter').value;$('apiKeyAccount').innerHTML=accounts.map(function(a){return '<option value="'+a.id+'"'+(String(a.id)===String(selected)?' selected':'')+'>'+escapeHTML(a.name)+' · '+escapeHTML(a.provider)+'</option>'}).join('');$('keyAccountFilter').innerHTML='<option value="">全部订阅</option>'+accounts.map(function(a){return '<option value="'+a.id+'">'+escapeHTML(a.name)+'</option>'}).join('');if(filter)$('keyAccountFilter').value=filter}
      function renderAPIKeys(){fillAPIKeyAccountOptions($('apiKeyAccount').value);var query=$('keySearch').value.trim().toLowerCase();var accountID=$('keyAccountFilter').value;var filtered=keys.filter(function(k){return(!accountID||String(k.subscription_id)===accountID)&&(!query||(k.name+' '+k.key_prefix+' '+k.subscription_name+' '+k.provider).toLowerCase().includes(query))});if(!filtered.length){$('keyTable').innerHTML='<div class="empty">暂无 API Key。先接入订阅，再在这里签发。</div>';return}$('keyTable').innerHTML='<table><thead><tr><th>Key</th><th>订阅</th><th>平台</th><th>状态</th><th>RPM</th><th>创建时间</th><th style="text-align:right">操作</th></tr></thead><tbody>'+filtered.map(function(k){return '<tr><td><div class="account-name">'+escapeHTML(k.name)+'</div><div class="key subtle">'+escapeHTML(k.key_prefix)+'…</div></td><td>'+escapeHTML(k.subscription_name)+'</td><td><div class="provider-name">'+providerIcon(k.provider)+escapeHTML(k.provider)+'</div></td><td><span class="badge '+(k.enabled?'ok':'off')+'">'+(k.enabled?'已启用':'已停用')+'</span></td><td>'+(k.rpm_limit==null?'—':formatNumber(k.rpm_limit))+'</td><td class="subtle">'+formatTime(k.created_at)+'</td><td><div class="actions">'+iconActionButton('ccswitch',k.id,'CC Switch','ccswitch')+iconActionButton('edit',k.id,'编辑','edit')+iconActionButton('delete',k.id,'删除','trash','btn-danger')+'</div></td></tr>'}).join('')+'</tbody></table>'}
      function closeAPIKeyForm(){editingKeyID=0;$('apiKeyFormModal').hidden=true}
      function openCreateAPIKey(){if(!accounts.length){toast('请先接入一个订阅账号',true);return}$('apiKeyForm').reset();editingKeyID=0;fillAPIKeyAccountOptions('');$('apiKeyEnabledField').hidden=true;$('deleteAPIKeyButton').hidden=true;$('resetAPIKeyButton').hidden=true;$('apiKeyAccount').disabled=false;$('apiKeyFormTitle').textContent='签发 API Key';$('saveAPIKeyButton').textContent='签发 Key';$('apiKeyFormModal').hidden=false;$('apiKeyName').focus()}
      function openEditAPIKey(key){$('apiKeyForm').reset();editingKeyID=key.id;fillAPIKeyAccountOptions(key.subscription_id);$('apiKeyAccount').value=String(key.subscription_id);$('apiKeyAccount').disabled=true;$('apiKeyName').value=key.name;$('apiKeyEnabled').value=key.enabled?'1':'0';$('apiKeyRpmLimit').value=key.rpm_limit||'';$('apiKeyExpiresAt').value='';$('apiKeyEnabledField').hidden=false;$('deleteAPIKeyButton').hidden=false;$('resetAPIKeyButton').hidden=false;$('apiKeyFormTitle').textContent='编辑 API Key';$('saveAPIKeyButton').textContent='保存修改';$('apiKeyFormModal').hidden=false;$('apiKeyName').focus()}
      async function saveAPIKey(event){event.preventDefault();var button=$('saveAPIKeyButton');button.disabled=true;try{var payload={name:$('apiKeyName').value.trim(),rpm_limit:$('apiKeyRpmLimit').value?Number($('apiKeyRpmLimit').value):null};if($('apiKeyExpiresAt').value)payload.expires_at=new Date($('apiKeyExpiresAt').value).toISOString();if(editingKeyID){payload.enabled=$('apiKeyEnabled').value==='1';await request('/api/api-keys/'+editingKeyID,{method:'PUT',body:JSON.stringify(payload)});closeAPIKeyForm();toast('API Key 已更新');await loadData();return}payload.subscription_id=Number($('apiKeyAccount').value);var result=await request('/api/api-keys',{method:'POST',body:JSON.stringify(payload)});closeAPIKeyForm();showKey(result.api_key,'API Key 已签发',result.key);await loadData()}catch(e){toast(e.message,true)}finally{button.disabled=false}}
      function ccSwitchApp(provider){return({claude:'claude',codex:'codex',grok:'grokbuild'}[provider]||'claude')}
      function ccSwitchEndpoint(provider){var origin=location.origin;if(provider==='claude')return origin+'/claude';if(provider==='codex')return origin+'/codex/v1';if(provider==='grok')return origin+'/grok/v1';return origin}
      function openCCSwitch(key,plaintext){if(!key)return;if(!plaintext){toast('没有可用的 API Key，无法导入 CC Switch',true);return}var params=new URLSearchParams({resource:'provider',app:ccSwitchApp(key.provider),name:key.name||('UniSub '+key.subscription_name),endpoint:ccSwitchEndpoint(key.provider),homepage:location.origin,apiKey:plaintext});window.location.href='ccswitch://v1/import?'+params.toString();toast('已唤起 CC Switch')}
      async function launchCCSwitch(key){if(!key)return;var plaintext=plaintextKeys[key.id];if(!plaintext){try{var detail=await request('/api/api-keys/'+key.id);plaintext=detail.api_key||(detail.key&&detail.key.api_key)||'';if(plaintext)plaintextKeys[key.id]=plaintext}catch(e){toast(e.message,true);return}}if(!plaintext){if(!confirm('这把 Key 签发时没有保存明文。重置后会带入 CC Switch，旧 Key 将立即失效。继续？'))return;try{var result=await request('/api/api-keys/'+key.id+'/reset',{method:'POST'});plaintext=result.api_key;if(plaintext)plaintextKeys[key.id]=plaintext;await loadData()}catch(e){toast(e.message,true);return}}openCCSwitch(key,plaintext)}
      async function keyAction(event){var button=event.target.closest('[data-action]');if(!button)return;var key=keys.find(function(item){return item.id===Number(button.dataset.id)});if(!key)return;if(button.dataset.action==='ccswitch'){launchCCSwitch(key);return}if(button.dataset.action==='delete'){deleteAPIKey(key);return}openEditAPIKey(key)}
      async function resetEditingAPIKey(){var key=keys.find(function(item){return item.id===editingKeyID});if(!key||!confirm('确定重置 '+key.name+' ？旧 Key 将立即失效。'))return;try{var result=await request('/api/api-keys/'+key.id+'/reset',{method:'POST'});closeAPIKeyForm();showKey(result.api_key,'API Key 已重置',key);await loadData()}catch(e){toast(e.message,true)}}
      async function deleteAPIKey(key){if(!key||!confirm('确定删除 '+key.name+' ？使用该 Key 的请求将立即失败。'))return;try{await request('/api/api-keys/'+key.id,{method:'DELETE'});closeAPIKeyForm();toast('API Key 已删除');await loadData()}catch(e){toast(e.message,true)}}
      async function deleteEditingAPIKey(){return deleteAPIKey(keys.find(function(item){return item.id===editingKeyID}))}
      function roleLabel(role){return role==='admin'?'管理员':'成员'}
      function renderUsers(){if(!isAdmin()){$('userTable').innerHTML='<div class="empty">只有管理员可以管理用户。</div>';return}if(!users.length){$('userTable').innerHTML='<div class="empty">暂无用户。</div>';return}$('userTable').innerHTML='<table><thead><tr><th>用户名</th><th>角色</th><th>状态</th><th style="text-align:right">操作</th></tr></thead><tbody>'+users.map(function(u){var self=currentUser&&u.id===currentUser.id;return '<tr><td><div class="account-name">'+escapeHTML(u.username)+(self?' <span class="subtle">当前</span>':'')+'</div></td><td>'+roleLabel(u.role)+'</td><td><span class="badge '+(u.enabled?'ok':'off')+'">'+(u.enabled?'已启用':'已停用')+'</span></td><td><div class="actions"><button class="btn" type="button" data-user-action="reset-password" data-id="'+u.id+'">重置密码</button><button class="btn" type="button" data-user-action="role" data-id="'+u.id+'">'+(u.role==='admin'?'设为成员':'设为管理员')+'</button><button class="btn" type="button" data-user-action="toggle" data-id="'+u.id+'">'+(u.enabled?'停用':'启用')+'</button><button class="btn btn-danger" type="button" data-user-action="delete" data-id="'+u.id+'" '+(self?'disabled':'')+'>删除</button></div></td></tr>'}).join('')+'</tbody></table>'}
      function openUserModal(){$('userForm').reset();$('userRole').value='user';$('userModal').hidden=false;$('userName').focus()}
      function closeUserModal(){$('userModal').hidden=true}
      var resettingUserID=0;
      function openResetPasswordModal(user){if(!user)return;resettingUserID=user.id;$('resetPasswordForm').reset();$('resetPasswordUsername').textContent=user.username;$('resetPasswordModal').hidden=false;$('resetPasswordValue').focus()}
      function closeResetPasswordModal(){resettingUserID=0;$('resetPasswordModal').hidden=true}
      async function saveResetPassword(event){event.preventDefault();if(!resettingUserID)return;if($('resetPasswordValue').value!==$('resetPasswordConfirm').value){toast('两次输入的新密码不一致',true);return}try{await request('/api/users/'+resettingUserID+'/password',{method:'POST',body:JSON.stringify({password:$('resetPasswordValue').value})});closeResetPasswordModal();toast('密码已重置')}catch(e){toast(e.message,true)}}
      async function saveUser(event){event.preventDefault();try{await request('/api/users',{method:'POST',body:JSON.stringify({username:$('userName').value.trim(),password:$('userPassword').value,role:$('userRole').value})});closeUserModal();toast('用户已创建');await loadData()}catch(e){toast(e.message,true)}}
      async function userAction(event){var button=event.target.closest('[data-user-action]');if(!button||button.disabled)return;var user=users.find(function(item){return item.id===Number(button.dataset.id)});if(!user)return;var action=button.dataset.userAction;try{if(action==='reset-password'){openResetPasswordModal(user);return}if(action==='role'){await request('/api/users/'+user.id,{method:'PUT',body:JSON.stringify({role:user.role==='admin'?'user':'admin',enabled:user.enabled})});toast('角色已更新');await loadData();return}if(action==='toggle'){await request('/api/users/'+user.id,{method:'PUT',body:JSON.stringify({role:user.role,enabled:!user.enabled})});toast(user.enabled?'用户已停用':'用户已启用');await loadData();return}if(action==='delete'){if(!confirm('确定删除用户 '+user.username+' ？'))return;await request('/api/users/'+user.id,{method:'DELETE'});toast('用户已删除');await loadData()}}catch(e){toast(e.message,true)}}
      async function changePassword(event){event.preventDefault();if($('newPassword').value!==$('confirmPassword').value){toast('两次输入的新密码不一致',true);return}try{await request('/api/password',{method:'PUT',body:JSON.stringify({current_password:$('currentPassword').value,new_password:$('newPassword').value})});$('passwordForm').reset();toast('密码已更新')}catch(e){toast(e.message,true)}}
      $('loginForm').addEventListener('submit',login);if($('usageRange1D')){$('usageRange1D').onclick=function(){setUsageRange('1d')};$('usageRange1W').onclick=function(){setUsageRange('1w')};$('usageRange1M').onclick=function(){setUsageRange('1m')};$('usageRangeCUSTOM').onclick=function(){setUsageRange('custom')};$('usageRangeLoad').onclick=function(){loadUsageBySubscription()}};$('logoutButton').addEventListener('click',logout);$('refreshButton').addEventListener('click',refreshData);$('pageAddButton').addEventListener('click',openAccountModal);$('accountForm').addEventListener('submit',saveAccount);$('accountProvider').addEventListener('change',updateCredentialHint);$('authType').addEventListener('change',updateCredentialHint);$('accountSearch').addEventListener('input',renderAccounts);$('providerFilter').addEventListener('change',renderAccounts);$('accountTable').addEventListener('click',accountAction);$('deleteAccountButton').addEventListener('click',deleteEditingAccount);$('refreshUsageButton').addEventListener('click',refreshEditingUsage);$('pageAddKeyButton').addEventListener('click',openCreateAPIKey);$('apiKeyForm').addEventListener('submit',saveAPIKey);$('keySearch').addEventListener('input',renderAPIKeys);$('keyAccountFilter').addEventListener('change',renderAPIKeys);$('keyTable').addEventListener('click',keyAction);$('deleteAPIKeyButton').addEventListener('click',deleteEditingAPIKey);$('resetAPIKeyButton').addEventListener('click',resetEditingAPIKey);$('passwordForm').addEventListener('submit',changePassword);$('pageAddUserButton').addEventListener('click',openUserModal);$('userForm').addEventListener('submit',saveUser);$('resetPasswordForm').addEventListener('submit',saveResetPassword);$('userTable').addEventListener('click',userAction);$('copyKeyButton').addEventListener('click',function(){copyText($('newAPIKey').value)});$('ccSwitchFromKeyModal').addEventListener('click',function(){openCCSwitch(pendingCCSwitchKey||keys.find(function(item){return item.id===editingKeyID}),$('newAPIKey').value)});$('logTable').addEventListener('click',logTableClick);$('logModalBody').addEventListener('click',logModalClick);$('logPager').addEventListener('click',logPagerClick);$('logAccountFilter').addEventListener('change',resetLogOffsetAndLoad);$('logStatusFilter').addEventListener('change',resetLogOffsetAndLoad);$('logSearch').addEventListener('input',function(){clearTimeout(logSearchTimer);logSearchTimer=setTimeout(resetLogOffsetAndLoad,250)});
      if($('userUsageRange1D')){$('userUsageRange1D').onclick=function(){setUserUsageRange('1d')};$('userUsageRange1W').onclick=function(){setUserUsageRange('1w')};$('userUsageRange1M').onclick=function(){setUserUsageRange('1m')};$('userUsageRangeCUSTOM').onclick=function(){setUserUsageRange('custom')};$('userUsageRangeLoad').onclick=function(){loadUsageByUser()}}
