      $('usageBySubscriptionTable').addEventListener('click',usageSortClick);$('usageByUserTable').addEventListener('click',usageSortClick);
      document.querySelectorAll('.nav button').forEach(function(el){el.addEventListener('click',function(){navigate(el.dataset.page)})});document.querySelectorAll('[data-close]').forEach(function(el){el.addEventListener('click',closeAccountModal)});document.querySelectorAll('[data-key-close]').forEach(function(el){el.addEventListener('click',function(){$('keyModal').hidden=true;$('newAPIKey').value=''})});document.querySelectorAll('[data-key-form-close]').forEach(function(el){el.addEventListener('click',closeAPIKeyForm)});document.querySelectorAll('[data-user-close]').forEach(function(el){el.addEventListener('click',closeUserModal)});document.querySelectorAll('[data-reset-password-close]').forEach(function(el){el.addEventListener('click',closeResetPasswordModal)});document.querySelectorAll('[data-log-close]').forEach(function(el){el.addEventListener('click',function(){$('logModal').hidden=true})});
